// Normaliza las actividades de Moodle al catálogo de KAIROS (INF, ACT, TAR, TAL, QUI, EXP, PRO, PAR, FIN).
// No inventa datos: el calendario de Moodle NO trae ponderación, por eso "ponderacion" va en null.
const all = $input.all().map(i => i.json || {});
const fallo = all.find(d => d.exception || d.errorcode || d.error);
const events = all.flatMap(d => Array.isArray(d.events) ? d.events : []);

const quitarTildes = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const NIVEL = { INF: 1, ACT: 2, TAR: 3, TAL: 3, QUI: 4, EXP: 4, PRO: 4, PAR: 5, FIN: 5 };
const REGLAS = [
  ['FIN', /entrega final|proyecto final|trabajo final|examen final/],
  ['PAR', /parcial|examen|sustentacion/],
  ['QUI', /quiz|prueba corta|evaluacion corta/],
  ['EXP', /exposicion|presentacion oral/],
  ['PRO', /proyecto/],
  ['TAL', /taller/],
  ['ACT', /actividad|ejercicio|lectura/],
  ['INF', /aviso|informacion|comunicado/],
  ['TAR', /tarea|trabajo escrito|entrega/],
];
const POR_MODULO = { assign: 'TAR', quiz: 'QUI', workshop: 'TAL' };
const TIPO_LEGADO = { PAR: 'examen', QUI: 'examen', FIN: 'examen', TAL: 'taller', PRO: 'proyecto', TAR: 'tarea' };
const limpiar = n => String(n || '').replace(/\s+(is due|vence|se vence|closes|se cierra|opens|se abre|abre)\s*$/i, '').trim();

const ahora = Date.now() / 1000;
const actividades = events
  .filter(e => !e.action || e.action.actionable !== false)
  .map(e => {
    const nombre = limpiar(e.activityname || e.name);
    const texto = quitarTildes(nombre + ' ' + (e.name || ''));
    const porNombre = REGLAS.find(([, re]) => re.test(texto));
    const codigo = porNombre ? porNombre[0] : (POR_MODULO[String(e.modulename || '').toLowerCase()] || null);
    return {
      materia: (e.course && e.course.fullname) || '',
      tematica: e.activityname || e.name || '',
      actividad: nombre,
      tipo: TIPO_LEGADO[codigo] || 'otro',
      codigo,
      nivel_importancia: codigo ? NIVEL[codigo] : null,
      fecha_iso: e.timesort ? new Date(e.timesort * 1000).toISOString() : null,
      dias_restantes: e.timesort ? Math.ceil((e.timesort - ahora) / 86400) : null,
      ponderacion: null,
      url_moodle: e.url || '',
      estado: 'pendiente',
      // Se pide confirmación si no hubo coincidencia por nombre (solo módulo o sin tipo).
      requiere_confirmacion: !porNombre,
    };
  })
  .sort((a, b) => String(a.fecha_iso).localeCompare(String(b.fecha_iso)));

const error = fallo
  ? (fallo.message || (fallo.error && fallo.error.message) || fallo.exception || 'No se pudo consultar Moodle')
  : null;
return [{ json: { total: actividades.length, actividades, error } }];
